import numpy as np,json
from PIL import Image
D=np.load('/app/output/initial_depth_over_shoulder_left_camera.npy')
I=np.array(Image.open('/app/output/initial_over_shoulder_left_camera.jpg'))
K=np.array([[500,0,640],[0,500,360],[0,0,1.]])
E=np.array(json.load(open('/app/output/spec.json'))['cameras']['over_shoulder_left_camera']['extrinsic_cv'])
R,t=E[:,:3],E[:,3]
def xyz(u,v):
 d=float(D[v,u]); pc=np.linalg.inv(K)@np.array([u,v,1.])*d
 return np.linalg.inv(R)@(pc-t)
# report table plane samples (relative world z)
for (u,v) in [(700,470),(700,500),(700,550),(800,550),(850,550),(650,450),(900,480),(750,400),(760,410),(775,415),(780,430),(860,410),(850,420),(870,430)]:
 print((u,v),I[v,u].tolist(),round(float(D[v,u]),3),np.round(xyz(u,v),4))
# look for local rgb + depth extents around cans
for name,(x0,x1,y0,y1) in {'tomato':(735,810,375,470),'tuna':(815,900,375,470)}.items():
 print('\n',name)
 for v in range(y0,y1,5):
  vals=[]
  for u in range(x0,x1,5):
   pix=I[v,u]
   d=D[v,u]
   if d>0 and (pix[0]>pix[1]*1.25 or pix[2]>pix[0]*1.1): vals.append((u,round(float(d),2),tuple(pix)))
  if vals: print(v,vals[:12])
